# Mains answer practice: original questions in the UPSC Mains style, with points a good answer covers.
# m = marks, w = words, min = minutes. 10-markers: 150 words, 7 min; 15-markers: 250 words, 11 min.
def Q(id, q, m, dw, pts):
    w, mn = (150, 7) if m == 10 else ((250, 11) if m == 15 else (1100, 90))
    return {"id": id, "q": q, "m": m, "w": w, "min": mn, "dw": dw, "pts": pts}

